import { HeadContent, Scripts, createRootRoute, Link, Outlet } from '@tanstack/react-router'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { useStore } from '@tanstack/react-store'
import * as React from 'react'
import { LayoutDashboardIcon, CheckSquareIcon, FileTextIcon, UsersIcon } from 'lucide-react'
import { appStore, setTab, type TabType } from '~/store'
import { cn } from '~/lib/utils'
import appCss from '~/styles/app.css?url'

function makeQueryClient() {
  return new QueryClient({
    defaultOptions: { queries: { staleTime: 1000 * 60 * 5, retry: 1 } },
  })
}
let browserQueryClient: QueryClient | undefined
function getQueryClient() {
  if (typeof window === 'undefined') return makeQueryClient()
  if (!browserQueryClient) browserQueryClient = makeQueryClient()
  return browserQueryClient
}

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: 'utf-8' },
      { name: 'viewport', content: 'width=device-width, initial-scale=1' },
      { title: 'TanStack Full Demo' },
    ],
    links: [{ rel: 'stylesheet', href: appCss }],
  }),
  // Use component instead of shellComponent to avoid SSR issues with hooks
  component: RootComponent,
})

const tabs = [
  { id: 'todos' as TabType, label: 'Todos', href: '/todos', icon: CheckSquareIcon },
  { id: 'posts' as TabType, label: 'Posts', href: '/posts', icon: FileTextIcon },
  { id: 'users' as TabType, label: 'Users', href: '/users', icon: UsersIcon },
]

function Header() {
  // useStore with explicit identity selector to fix SSR crash
  const activeTab = useStore(appStore, (s) => s.activeTab)
  return (
    <header className="border-b bg-white/80 backdrop-blur sticky top-0 z-40">
      <div className="max-w-6xl mx-auto px-4 h-14 flex items-center gap-3">
        <Link to="/" data-testid="brand-link" className="flex items-center gap-2 font-bold text-foreground hover:text-primary transition-colors min-w-0 shrink">
          <LayoutDashboardIcon className="w-5 h-5 text-primary" />
          TanStack Demo
        </Link>
        <span className="hidden sm:block text-xs text-muted-foreground border-l pl-3 ml-1">
          Query · Table · Virtual · Form · Store
        </span>
        <nav className="ml-auto flex gap-1 shrink-0">
          {tabs.map(tab => (
            <Link key={tab.id} to={tab.href} data-testid={`nav-${tab.id}`} onClick={() => setTab(tab.id)}
              className={cn(
                'flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium transition-colors',
                activeTab === tab.id
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
              )}>
              <tab.icon className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">{tab.label}</span>
            </Link>
          ))}
        </nav>
      </div>
    </header>
  )
}

function RootComponent() {
  const [hydrated, setHydrated] = React.useState(false)
  const queryClient = getQueryClient()
  React.useEffect(() => setHydrated(true), [])
  return (
    <html lang="en">
      <head><HeadContent /></head>
      <body>
        <QueryClientProvider client={queryClient}>
          <div className="min-h-screen bg-gradient-to-br from-slate-50 via-violet-50/20 to-indigo-50/30">
            <Header />
            <main className="max-w-6xl mx-auto px-4 py-8">
              <Outlet />
            </main>
          </div>
          <ReactQueryDevtools initialIsOpen={false} />
        </QueryClientProvider>
        <span data-testid="app-ready" hidden>{hydrated ? 'ready' : 'loading'}</span>
        <Scripts />
      </body>
    </html>
  )
}

import { createFileRoute } from '@tanstack/react-router'
import { useQuery } from '@tanstack/react-query'
import { useVirtualizer } from '@tanstack/react-virtual'
import { useReactTable, getCoreRowModel, getSortedRowModel, getFilteredRowModel, getPaginationRowModel, flexRender, type ColumnDef, type SortingState } from '@tanstack/react-table'
import * as React from 'react'
import { ArrowUpDownIcon, ArrowUpIcon, ArrowDownIcon, FileTextIcon, LayoutListIcon, TableIcon, LoaderIcon } from 'lucide-react'
import { Button } from '~/components/ui/button'
import { Input } from '~/components/ui/input'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '~/components/ui/card'
import { Badge } from '~/components/ui/badge'
