const API = 'https://jsonplaceholder.typicode.com'
interface Post { id: number; userId: number; title: string; body: string }

export const Route = createFileRoute('/posts')({ component: PostsPage })

function PostsPage() {
  const viewMode = useStore(appStore, (s) => s.viewMode)
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [globalFilter, setGlobalFilter] = React.useState('')

  // ── TanStack Query ────────────────────────────────────────────────────────
  const { data: posts = [], isLoading } = useQuery({
    queryKey: ['posts'],
    queryFn: async (): Promise<Post[]> => {
      const res = await fetch(`${API}/posts`)
      return res.json()
    },
    staleTime: 1000 * 60 * 10,
  })

  // ── TanStack Table columns ────────────────────────────────────────────────
  const columns: ColumnDef<Post>[] = [
    { accessorKey: 'id', header: 'ID', size: 60,
      cell: info => <Badge variant="outline" className="font-mono text-xs">#{info.getValue<number>()}</Badge> },
    { accessorKey: 'userId', header: 'User', size: 80,
      cell: info => <Badge variant="secondary">User {info.getValue<number>()}</Badge> },
    { accessorKey: 'title', header: 'Title', cell: info => (
      <span className="font-medium text-sm line-clamp-1">{info.getValue<string>()}</span>
    )},
    { accessorKey: 'body', header: 'Body', enableSorting: false, meta: { className: 'hidden md:table-cell' }, cell: info => (
      <span className="text-xs text-muted-foreground line-clamp-2">{info.getValue<string>()}</span>
    )},
  ]

  // ── TanStack Table ────────────────────────────────────────────────────────
  const table = useReactTable({
    data: posts,
    columns,
    state: { sorting, globalFilter },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: { pagination: { pageSize: 10 } },
  })

  // ── TanStack Virtual (virtual list view) ─────────────────────────────────
  const parentRef = React.useRef<HTMLDivElement>(null)
  const rowVirtualizer = useVirtualizer({
    count: posts.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 72,
    overscan: 5,
  })

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h2 data-testid="posts-heading" className="text-2xl font-bold flex items-center gap-2">
            <FileTextIcon className="w-6 h-6 text-blue-500" /> Posts
          </h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            <span className="text-blue-500 font-medium">@tanstack/react-table</span> · <span className="text-blue-500 font-medium">@tanstack/react-virtual</span> · <span className="text-blue-500 font-medium">@tanstack/react-query</span>
          </p>
        </div>
        <div className="flex gap-2 items-center">
          <Badge variant="secondary">{posts.length} posts</Badge>
          <div className="flex border rounded-md overflow-hidden">
            <Button data-testid="posts-table-view" variant={viewMode === 'table' ? 'default' : 'ghost'} size="sm" className="rounded-none h-8 px-2" onClick={() => setViewMode('table')}>
              <TableIcon className="w-4 h-4" />
            </Button>
            <Button data-testid="posts-virtual-view" variant={viewMode === 'virtual' ? 'default' : 'ghost'} size="sm" className="rounded-none h-8 px-2" onClick={() => setViewMode('virtual')}>
              <LayoutListIcon className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </div>

      {isLoading && (
        <div className="flex items-center justify-center py-20 text-muted-foreground gap-2">
          <LoaderIcon className="w-5 h-5 animate-spin" /> Loading posts...
        </div>
      )}

      {/* TABLE VIEW — TanStack Table */}
      {!isLoading && viewMode === 'table' && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Table View <Badge variant="outline" className="ml-2 font-mono text-xs">@tanstack/react-table</Badge></CardTitle>
            <CardDescription>Sorting, filtering, and pagination built-in</CardDescription>
            <Input data-testid="posts-filter" placeholder="Filter posts..." value={globalFilter} onChange={e => setGlobalFilter(e.target.value)} className="h-8 mt-2" />
          </CardHeader>
          <Separator />
          <CardContent className="p-0 overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-muted/40 border-b">
                {table.getHeaderGroups().map(hg => (
                  <tr key={hg.id}>
                    {hg.headers.map(header => (
                      <th key={header.id} className={cn("text-left px-4 py-2.5 font-medium text-muted-foreground text-xs uppercase tracking-wider", (header.column.columnDef.meta as any)?.className)}
                        style={{ width: header.getSize() }}>
                        {header.isPlaceholder ? null : (
                          <div className={cn('flex items-center gap-1', header.column.getCanSort() && 'cursor-pointer select-none hover:text-foreground')}
                            onClick={header.column.getToggleSortingHandler()}>
                            {flexRender(header.column.columnDef.header, header.getContext())}
                            {header.column.getCanSort() && (
                              header.column.getIsSorted() === 'asc' ? <ArrowUpIcon className="w-3 h-3" /> :
                              header.column.getIsSorted() === 'desc' ? <ArrowDownIcon className="w-3 h-3" /> :
                              <ArrowUpDownIcon className="w-3 h-3 opacity-40" />
                            )}
                          </div>
                        )}
                      </th>
                    ))}
                  </tr>
                ))}
              </thead>
              <tbody className="divide-y">
                {table.getRowModel().rows.map(row => (
                  <tr key={row.id} className="hover:bg-muted/30 transition-colors">
                    {row.getVisibleCells().map(cell => (
                      <td key={cell.id} className={cn("px-4 py-3", (cell.column.columnDef.meta as any)?.className)}>
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </CardContent>
          <Separator />
          <div className="flex items-center justify-between px-4 py-3">
            <span className="text-xs text-muted-foreground">
              Page {table.getState().pagination.pageIndex + 1} of {table.getPageCount()} · {table.getFilteredRowModel().rows.length} results
            </span>
            <div className="flex gap-1">
              <Button variant="outline" size="sm" onClick={() => table.previousPage()} disabled={!table.getCanPreviousPage()} className="h-7 px-2 text-xs">Prev</Button>
              <Button variant="outline" size="sm" onClick={() => table.nextPage()} disabled={!table.getCanNextPage()} className="h-7 px-2 text-xs">Next</Button>
            </div>
          </div>
        </Card>
      )}

      {/* VIRTUAL LIST VIEW — TanStack Virtual */}
      {!isLoading && viewMode === 'virtual' && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Virtual List <Badge variant="outline" className="ml-2 font-mono text-xs">@tanstack/react-virtual</Badge></CardTitle>
            <CardDescription>All 100 posts rendered virtually — only visible rows in DOM</CardDescription>
          </CardHeader>
          <Separator />
          <div ref={parentRef} className="h-[500px] overflow-auto">
            <div style={{ height: `${rowVirtualizer.getTotalSize()}px`, position: 'relative' }}>
              {rowVirtualizer.getVirtualItems().map(vItem => {
                const post = posts[vItem.index]
                return (
                  <div key={vItem.key} style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: `${vItem.size}px`, transform: `translateY(${vItem.start}px)` }}
                    className="flex items-start gap-3 px-4 py-3 border-b hover:bg-muted/30 transition-colors">
                    <Badge variant="outline" className="font-mono text-xs shrink-0 mt-0.5">#{post.id}</Badge>
                    <div className="min-w-0">
                      <p className="text-sm font-medium line-clamp-1">{post.title}</p>
                      <p className="text-xs text-muted-foreground line-clamp-1 mt-0.5">{post.body}</p>
                    </div>
                    <Badge variant="secondary" className="hidden sm:flex shrink-0 text-xs">User {post.userId}</Badge>
                  </div>
                )
              })}
            </div>
          </div>
          <div className="px-4 py-2 text-xs text-muted-foreground border-t">
            Showing {rowVirtualizer.getVirtualItems().length} of {posts.length} rows in DOM
          </div>
        </Card>
      )}
    </div>
  )
}

import { createFileRoute } from '@tanstack/react-router'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useStore } from '@tanstack/react-store'
import { useForm } from '@tanstack/react-form'
import * as React from 'react'
import { PlusIcon, Trash2Icon, LoaderIcon, CheckSquareIcon } from 'lucide-react'
import { Button } from '~/components/ui/button'
import { Input } from '~/components/ui/input'
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from '~/components/ui/card'
import { Badge } from '~/components/ui/badge'
import { Checkbox } from '~/components/ui/checkbox'
import { Label } from '~/components/ui/label'
import { Separator } from '~/components/ui/separator'
import { appStore, setSearchQuery } from '~/store'
import { cn } from '~/lib/utils'

const API = 'https://jsonplaceholder.typicode.com'

interface Todo { id: number; userId: number; title: string; completed: boolean }

// ── TanStack Query: fetch todos ──────────────────────────────────────────────
const todosQuery = {
  queryKey: ['todos'],
  queryFn: async (): Promise<Todo[]> => {
    const res = await fetch(`${API}/todos?_limit=20`)
    return res.json()
  },
}

export const Route = createFileRoute('/todos')({
  loader: async () => { // no-op loader, query handled by useQuery on client
    return null
  },
  component: TodosPage,
})

type FilterType = 'all' | 'active' | 'completed'

function TodosPage() {
  const queryClient = useQueryClient()
  const [filter, setFilter] = React.useState<FilterType>('all')
  const [titleError, setTitleError] = React.useState<string | null>(null)
  const [titleValue, setTitleValue] = React.useState('')
  // ── TanStack Store: global search ────────────────────────────────────────
  const searchQuery = useStore(appStore, (s) => s.searchQuery)

  // ── TanStack Query: useQuery ─────────────────────────────────────────────
  const { data: todos = [], isLoading, isError } = useQuery(todosQuery)

  // ── TanStack Query: useMutation (toggle) ─────────────────────────────────
  const toggleMutation = useMutation({
    mutationFn: async (todo: Todo) => {
      await fetch(`${API}/todos/${todo.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ completed: !todo.completed }),
      })
      return todo
    },
    onMutate: async (todo) => {
      await queryClient.cancelQueries({ queryKey: ['todos'] })
      const prev = queryClient.getQueryData<Todo[]>(['todos'])
      queryClient.setQueryData<Todo[]>(['todos'], old =>
        old?.map(t => t.id === todo.id ? { ...t, completed: !t.completed } : t)
      )
      return { prev }
    },
    onError: (_err, _todo, ctx) => {
      if (ctx?.prev) queryClient.setQueryData(['todos'], ctx.prev)
    },
  })

  // ── TanStack Query: useMutation (delete) ─────────────────────────────────
  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      await fetch(`${API}/todos/${id}`, { method: 'DELETE' })
      return id
    },
    onMutate: async (id) => {
      await queryClient.cancelQueries({ queryKey: ['todos'] })
      const prev = queryClient.getQueryData<Todo[]>(['todos'])
      queryClient.setQueryData<Todo[]>(['todos'], old => old?.filter(t => t.id !== id))
      return { prev }
    },
    onError: (_err, _id, ctx) => {
      if (ctx?.prev) queryClient.setQueryData(['todos'], ctx.prev)
    },
  })

  // ── TanStack Query: useMutation (add) ────────────────────────────────────
  const addMutation = useMutation({
    mutationFn: async (title: string) => {
      const res = await fetch(`${API}/todos`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, completed: false, userId: 1 }),
      })
      return res.json() as Promise<Todo>
    },
    onMutate: async (title) => {
      await queryClient.cancelQueries({ queryKey: ['todos'] })
      const prev = queryClient.getQueryData<Todo[]>(['todos'])
      const optimistic: Todo = { id: Date.now(), userId: 1, title, completed: false }
      queryClient.setQueryData<Todo[]>(['todos'], old => [optimistic, ...(old ?? [])])
      return { prev }
    },
    onError: (_err, _title, ctx) => {
      if (ctx?.prev) queryClient.setQueryData(['todos'], ctx.prev)
    },
  })

  // ── TanStack Form ────────────────────────────────────────────────────────
  const form = useForm({
    defaultValues: { title: '' },
    onSubmit: async ({ value, formApi }) => {
      if (!value.title.trim()) {
        setTitleError('Title is required')
        return
      }
      setTitleError(null)
      addMutation.mutate(value.title.trim())
      formApi.reset()
      setTitleValue('')
    },
  })

  const filtered = todos.filter(t => {
    const matchFilter = filter === 'all' || (filter === 'active' ? !t.completed : t.completed)
    const matchSearch = t.title.toLowerCase().includes(searchQuery.toLowerCase())
    return matchFilter && matchSearch
  })

  const completedCount = todos.filter(t => t.completed).length
  const activeCount = todos.length - completedCount

  return (
    <div className="space-y-4">
      {/* Page header */}
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div>
          <h2 data-testid="todos-heading" className="text-2xl font-bold flex items-center gap-2">
            <CheckSquareIcon className="w-6 h-6 text-primary" /> Todos
          </h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            <span className="text-primary font-medium">@tanstack/react-query</span> · <span className="text-primary font-medium">@tanstack/react-form</span> · <span className="text-primary font-medium">@tanstack/store</span>
          </p>
        </div>
        <div className="flex gap-2">
          <Badge variant="secondary">{activeCount} active</Badge>
          <Badge variant="success">{completedCount} done</Badge>
        </div>
      </div>

      {/* Add form — TanStack Form */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Add Todo <Badge variant="outline" className="ml-2 font-mono text-xs">@tanstack/react-form</Badge></CardTitle>
          <CardDescription>useForm with validation and onSubmit</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={(e) => {
            e.preventDefault()
            const title = e.currentTarget.querySelector('input')?.value ?? ''
            if (!title.trim()) {
              setTitleError('Title is required')
              return
            }
            setTitleError(null)
            addMutation.mutate(title.trim())
            form.reset()
            setTitleValue('')
          }} className="flex gap-2">
            <form.Field name="title" validators={{ onChange: ({ value }) => !value.trim() ? 'Title is required' : undefined }}>
              {(field) => (
                <div className="flex-1 space-y-1">
                  <Input
                    data-testid="add-todo-input"
                    placeholder="Add a new task..."
                    value={field.state.value}
                    onChange={e => {
                      setTitleValue(e.target.value)
                      setTitleError(null)
                      field.handleChange(e.target.value)
                    }}
                    onBlur={field.handleBlur}
                    className={cn(field.state.meta.errors.length > 0 && field.state.meta.isTouched && 'border-destructive')}
                  />
                  {(titleError || (titleValue.length > 0 && !titleValue.trim()) || (field.state.meta.isTouched && field.state.meta.errors.length > 0)) && (
                    <p data-testid="add-todo-validation" className="text-xs text-destructive">{titleError ?? field.state.meta.errors[0]?.toString()}</p>
                  )}
                </div>
              )}
            </form.Field>
            <Button data-testid="add-todo-button" type="submit" disabled={addMutation.isPending} className="shrink-0">
              {addMutation.isPending ? <LoaderIcon className="w-4 h-4 animate-spin" /> : <PlusIcon className="w-4 h-4" />}
              Add
            </Button>
          </form>
        </CardContent>
      </Card>

      {/* Todo list — TanStack Query */}
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div>
              <CardTitle className="text-base">Todo List <Badge variant="outline" className="ml-2 font-mono text-xs">@tanstack/react-query</Badge></CardTitle>
              <CardDescription>useQuery + useMutation with optimistic updates</CardDescription>
            </div>
            <div className="flex gap-1 flex-wrap">
              {(['all','active','completed'] as FilterType[]).map(f => (
                <Button key={f} data-testid={`todo-filter-${f}`} variant={filter === f ? 'default' : 'ghost'} size="sm" onClick={() => setFilter(f)} className="h-7 px-2 text-xs capitalize">{f}</Button>
              ))}
            </div>
          </div>
          <div className="mt-2">
            <Input data-testid="todo-search" placeholder="Search todos... (TanStack Store)" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="h-8 text-xs" />
          </div>
        </CardHeader>
        <Separator />
        <CardContent className="p-0">
          {isLoading && (
            <div className="flex items-center justify-center py-12 text-muted-foreground gap-2">
              <LoaderIcon className="w-4 h-4 animate-spin" /> Loading...
            </div>
          )}
          {isError && <div className="text-center py-8 text-destructive text-sm">Failed to load todos</div>}
          {!isLoading && filtered.length === 0 && (
            <div className="text-center py-12 text-muted-foreground text-sm">No todos found</div>
          )}
          <ul className="divide-y">
            {filtered.map(todo => (
              <li key={todo.id} className="group flex items-center gap-3 px-4 py-3 hover:bg-muted/30 transition-colors">
                <Checkbox
                  checked={todo.completed}
                  onCheckedChange={() => toggleMutation.mutate(todo)}
                  disabled={toggleMutation.isPending}
                />
                <span className={cn('flex-1 text-sm', todo.completed && 'line-through text-muted-foreground')}>
                  {todo.title}
                </span>
                <Button variant="ghost" size="icon" className="h-7 w-7 opacity-0 group-hover:opacity-100 hover:text-destructive hover:bg-destructive/10"
                  onClick={() => deleteMutation.mutate(todo.id)}>
                  <Trash2Icon className="w-3.5 h-3.5" />
                </Button>
              </li>
            ))}
          </ul>
        </CardContent>
        <Separator />
        <CardFooter className="py-3 px-4 gap-3">
          <span className="text-xs text-muted-foreground">{completedCount}/{todos.length} completed</span>
          <div className="flex-1 h-1.5 rounded-full bg-muted overflow-hidden">
            <div className="h-full bg-primary rounded-full transition-all duration-500"
              style={{ width: `${todos.length ? (completedCount / todos.length) * 100 : 0}%` }} />
          </div>
        </CardFooter>
      </Card>
    </div>
  )
}

import { createFileRoute } from '@tanstack/react-router'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useReactTable, getCoreRowModel, getSortedRowModel, getFilteredRowModel, flexRender, type ColumnDef, type SortingState } from '@tanstack/react-table'
import { useForm } from '@tanstack/react-form'
import * as React from 'react'
import { UsersIcon, PencilIcon, CheckIcon, XIcon, LoaderIcon, ArrowUpDownIcon, ArrowUpIcon, ArrowDownIcon } from 'lucide-react'
import { Button } from '~/components/ui/button'
import { Input } from '~/components/ui/input'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '~/components/ui/card'
import { Badge } from '~/components/ui/badge'
import { Separator } from '~/components/ui/separator'
import { Label } from '~/components/ui/label'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '~/components/ui/dialog'
import { cn } from '~/lib/utils'

const API = 'https://jsonplaceholder.typicode.com'

interface User {
  id: number; name: string; username: string; email: string
  phone: string; website: string
  company: { name: string; catchPhrase: string }
  address: { city: string }
}

export const Route = createFileRoute('/users')({ component: UsersPage })

function UsersPage() {
  const queryClient = useQueryClient()
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [globalFilter, setGlobalFilter] = React.useState('')
  const [editingUser, setEditingUser] = React.useState<User | null>(null)
  const [dialogOpen, setDialogOpen] = React.useState(false)

  // ── TanStack Query ────────────────────────────────────────────────────────
  const { data: users = [], isLoading } = useQuery({
    queryKey: ['users'],
    queryFn: async (): Promise<User[]> => {
      const res = await fetch(`${API}/users`)
      return res.json()
    },
    staleTime: 1000 * 60 * 10,
  })

  // ── TanStack Query: useMutation (edit user) ───────────────────────────────
  const editMutation = useMutation({
    mutationFn: async ({ id, data }: { id: number; data: Partial<User> }) => {
      const res = await fetch(`${API}/users/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      })
      return res.json()
    },
    onMutate: async ({ id, data }) => {
      await queryClient.cancelQueries({ queryKey: ['users'] })
      const prev = queryClient.getQueryData<User[]>(['users'])
      queryClient.setQueryData<User[]>(['users'], old =>
        old?.map(u => u.id === id ? { ...u, ...data } : u)
      )
      return { prev }
    },
    onError: (_err, _vars, ctx) => {
      if (ctx?.prev) queryClient.setQueryData(['users'], ctx.prev)
    },
    onSuccess: () => setDialogOpen(false),
  })

  // ── TanStack Form ─────────────────────────────────────────────────────────
  const form = useForm({
    defaultValues: { name: '', email: '', phone: '', website: '' },
    onSubmit: async ({ value }) => {
      if (!editingUser) return
      editMutation.mutate({ id: editingUser.id, data: value })
    },
  })

  function openEdit(user: User) {
    setEditingUser(user)
    form.setFieldValue('name', user.name)
    form.setFieldValue('email', user.email)
    form.setFieldValue('phone', user.phone)
    form.setFieldValue('website', user.website)
    setDialogOpen(true)
  }

  // ── TanStack Table ────────────────────────────────────────────────────────
  const columns: ColumnDef<User>[] = [
    { accessorKey: 'id', header: 'ID', size: 50,
      cell: info => <span className="font-mono text-xs text-muted-foreground">#{info.getValue<number>()}</span> },
    { accessorKey: 'name', header: 'Name',
      cell: info => <span className="font-medium text-sm">{info.getValue<string>()}</span> },
    { accessorKey: 'email', header: 'Email',
      cell: info => <span className="text-sm text-muted-foreground">{info.getValue<string>()}</span> },
    { accessorKey: 'address', header: 'City', enableSorting: false, meta: { className: 'hidden md:table-cell' },
      cell: info => <Badge variant="secondary" className="text-xs">{info.getValue<User['address']>().city}</Badge> },
    { accessorKey: 'company', header: 'Company', enableSorting: false, meta: { className: 'hidden md:table-cell' },
      cell: info => <span className="text-xs text-muted-foreground">{info.getValue<User['company']>().name}</span> },
    {
      id: 'actions', header: '', size: 60,
      cell: ({ row }) => (
        <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-primary" onClick={() => openEdit(row.original)}>
          <PencilIcon className="w-3.5 h-3.5" />
        </Button>
      ),
    },
  ]

  const table = useReactTable({
    data: users,
    columns,
    state: { sorting, globalFilter },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
  })

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h2 data-testid="users-heading" className="text-2xl font-bold flex items-center gap-2">
            <UsersIcon className="w-6 h-6 text-green-500" /> Users
          </h2>
          <p className="text-sm text-muted-foreground mt-0.5">
            <span className="text-green-600 font-medium">@tanstack/react-query</span> · <span className="text-green-600 font-medium">@tanstack/react-table</span> · <span className="text-green-600 font-medium">@tanstack/react-form</span>
          </p>
        </div>
        <Badge variant="secondary">{users.length} users</Badge>
      </div>

      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">User Table <Badge variant="outline" className="ml-2 font-mono text-xs">@tanstack/react-table + @tanstack/react-form</Badge></CardTitle>
          <CardDescription>Sort columns · Filter · Click ✏️ to edit via TanStack Form dialog</CardDescription>
          <Input data-testid="users-filter" placeholder="Filter users..." value={globalFilter} onChange={e => setGlobalFilter(e.target.value)} className="h-8 mt-2" />
        </CardHeader>
        <Separator />
        <CardContent className="p-0 overflow-x-auto">
          {isLoading ? (
            <div className="flex items-center justify-center py-16 text-muted-foreground gap-2">
              <LoaderIcon className="w-4 h-4 animate-spin" /> Loading users...
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead className="bg-muted/40 border-b">
                {table.getHeaderGroups().map(hg => (
                  <tr key={hg.id}>
                    {hg.headers.map(header => (
                      <th key={header.id} className={cn("text-left px-4 py-2.5 font-medium text-muted-foreground text-xs uppercase tracking-wider", (header.column.columnDef.meta as any)?.className)} style={{ width: header.getSize() }}>
                        {header.isPlaceholder ? null : (
                          <div className={cn('flex items-center gap-1', header.column.getCanSort() && 'cursor-pointer select-none hover:text-foreground')}
                            onClick={header.column.getToggleSortingHandler()}>
                            {flexRender(header.column.columnDef.header, header.getContext())}
                            {header.column.getCanSort() && (
                              header.column.getIsSorted() === 'asc' ? <ArrowUpIcon className="w-3 h-3" /> :
                              header.column.getIsSorted() === 'desc' ? <ArrowDownIcon className="w-3 h-3" /> :
                              <ArrowUpDownIcon className="w-3 h-3 opacity-40" />
                            )}
                          </div>
                        )}
                      </th>
                    ))}
                  </tr>
                ))}
              </thead>
              <tbody className="divide-y">
                {table.getRowModel().rows.map(row => (
                  <tr key={row.id} className="hover:bg-muted/30 transition-colors">
                    {row.getVisibleCells().map(cell => (
                      <td key={cell.id} className={cn("px-4 py-3", (cell.column.columnDef.meta as any)?.className)}>
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </CardContent>
      </Card>

      {/* Edit dialog — TanStack Form */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit User <Badge variant="outline" className="ml-2 font-mono text-xs">@tanstack/react-form</Badge></DialogTitle>
          </DialogHeader>
          <form onSubmit={(e) => { e.preventDefault(); form.handleSubmit() }} className="space-y-4 mt-2">
            {(['name','email','phone','website'] as const).map(fieldName => (
              <form.Field key={fieldName} name={fieldName}
                validators={{ onChange: ({ value }) => !value.trim() ? `${fieldName} is required` : undefined }}>
                {(field) => (
                  <div className="space-y-1">
                    <Label htmlFor={fieldName} className="capitalize">{fieldName}</Label>
                    <Input
                      id={fieldName}
                      value={field.state.value}
                      onChange={e => field.handleChange(e.target.value)}
                      onBlur={field.handleBlur}
                      className={cn(field.state.meta.isTouched && field.state.meta.errors.length > 0 && 'border-destructive')}
                    />
                    {field.state.meta.isTouched && field.state.meta.errors.length > 0 && (
                      <p className="text-xs text-destructive">{field.state.meta.errors[0]?.toString()}</p>
                    )}
                  </div>
                )}
              </form.Field>
            ))}
            <div className="flex gap-2 justify-end pt-2">
              <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>
                <XIcon className="w-4 h-4 mr-1" /> Cancel
              </Button>
              <Button type="submit" disabled={editMutation.isPending}>
                {editMutation.isPending ? <LoaderIcon className="w-4 h-4 mr-1 animate-spin" /> : <CheckIcon className="w-4 h-4 mr-1" />}
                Save
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  )
}

